script:
const el=root_element.querySelector(".pmo-x");
const money=(v,cur)=>(v===null||v===undefined)?"—":frappe.format(v,{fieldtype:"Currency",currency:cur||undefined});
const intf=(v)=>(v===null||v===undefined)?"—":frappe.format(v,{fieldtype:"Int"});
const tile=(v,l,muted)=>`<div class="tile ${muted?'muted':''}"><div class="v">${v}</div><div class="l">${l}</div></div>`;
Promise.all([
  frappe.xcall("pmo.dashboard.portfolio_kpi",{filters:{metric:"active"}}),
  frappe.xcall("pmo.dashboard.economics_block"),
]).then(([a,e])=>{
  const ec=e.economics||{};const cur=ec.currency;const acc=!!ec.has_access;
  el.innerHTML=`<div class="tiles">`
    +tile(intf(a.value),"Proyectos activos")
    +tile(acc?money(ec.authorized_revenue,cur):"—","Valor autorizado",!acc)
    +tile(acc?money(ec.billed,cur):"—","Facturado",!acc)
    +tile(acc?money(ec.real_cost,cur):"—","Costo real",!acc)
    +`</div>`;
}).catch((err)=>{el.innerHTML=`<div class="empty">No se pudo cargar este panel.</div>`;console.error("PMO resumen ejecutivo",err);});

const el=root_element.querySelector(".pmo-se");
const money=(v,cur)=>(v===null||v===undefined)?"—":frappe.format(v,{fieldtype:"Currency",currency:cur||undefined});
frappe.xcall("pmo.dashboard.economics_block").then((d)=>{
  const e=d.economics||{};
  if(!e.has_access){el.innerHTML=`<div class="empty">Sin acceso económico.</div>`;return;}
  const cur=e.currency;
  const rows=[["Valor autorizado",e.authorized_revenue,"#5e9cff"],["Facturado",e.billed,"#29cd42"],["Costo real",e.real_cost,"#ed6396"]];
  const max=Math.max(1,...rows.map(r=>Math.abs(r[1]||0)));
  let h=`<div class="bars">`;
  for(const [l,v,col] of rows){
    const pct=Math.round((Math.abs(v||0)/max)*100);
    h+=`<div class="bar-row"><div class="bar-l">${l}</div>`
      +`<div class="bar-track"><div class="bar-fill" style="width:${pct}%;background:${col}"></div></div>`
      +`<div class="bar-v">${money(v,cur)}</div></div>`;
  }
  h+=`</div>`;
  let notes=[];
  if(e.excluded_no_proposal) notes.push(`${e.excluded_no_proposal} sin propuesta (excluidos)`);
  if(e.inconsistent) notes.push(`${e.inconsistent} con datos inconsistentes`);
  if(notes.length) h+=`<div class="trace">${notes.join(" · ")}</div>`;
  el.innerHTML=h;
}).catch((err)=>{el.innerHTML=`<div class="empty">No se pudo cargar este panel.</div>`;console.error("PMO situación económica",err);});

const el=root_element.querySelector(".pmo-x");
const intf=(v)=>(v===null||v===undefined)?"—":frappe.format(v,{fieldtype:"Int"});
const tile=(v,l)=>`<div class="tile"><div class="v">${v}</div><div class="l">${l}</div></div>`;
Promise.all([
  frappe.xcall("pmo.dashboard.portfolio_kpi",{filters:{metric:"requiring_attention"}}),
  frappe.xcall("pmo.dashboard.portfolio_kpi",{filters:{metric:"overdue_tasks"}}),
  frappe.xcall("pmo.dashboard.resource_kpi",{filters:{metric:"utilization"}}),
]).then(([a,b,c])=>{
  const u=(c.value===null||c.value===undefined)?"—":`${c.value}%`;
  el.innerHTML=`<div class="tiles">`
    +tile(intf(a.value),"En riesgo/desviados")
    +tile(intf(b.value),"Tareas vencidas")
    +tile(u,"Utilización")
    +`</div>`;
}).catch((err)=>{el.innerHTML=`<div class="empty">No se pudo cargar este panel.</div>`;console.error("PMO panorama operativo",err);});

const el=root_element.querySelector(".pmo-c");
const esc=(s)=>s==null?"":String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const money=(v,cur)=>(v===null||v===undefined)?"—":frappe.format(v,{fieldtype:"Currency",currency:cur||undefined});
const HP={on_track:["ok","En plan"],at_risk:["warn","En riesgo"],deviated:["bad","Desviado"]};
frappe.xcall("pmo.dashboard.customers_block").then((d)=>{
  const rows=d.customers||[];const econ=!!d.econ_access;const cur=d.currency||undefined;
  if(!rows.length){el.innerHTML=`<div class="empty">Sin proyectos con cliente asociado.</div>`;return;}
  let head=`<th>Cliente</th><th class="num">Proyectos activos</th><th>Salud</th>`;
  if(econ) head+=`<th class="num">Valor autorizado</th><th class="num">Facturado</th>`;
  let h=`<div class="wrap"><table><thead><tr>${head}</tr></thead><tbody>`;
  for(const r of rows){
    const hp=HP[r.health_key]||["gray",esc(r.health)];
    h+=`<tr><td><b>${esc(r.customer)}</b></td><td class="num">${r.projects}</td>`
      +`<td><span class="pill ${hp[0]}">${esc(hp[1])}</span></td>`;
    if(econ) h+=`<td class="num">${money(r.authorized,cur)}</td><td class="num">${money(r.billed,cur)}</td>`;
    h+=`</tr>`;
  }
  el.innerHTML=h+`</tbody></table></div>`;
}).catch((err)=>{el.innerHTML=`<div class="empty">No se pudo cargar este panel.</div>`;console.error("PMO cartera",err);});

style:
:host{display:block;width:100%}
.pmo-b{font-size:13px;color:var(--text-color);padding-top:2px}
.pmo-b h3{font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:var(--text-muted);margin:6px 0 8px}
.pmo-b .empty{padding:12px;border:1px dashed var(--border-color);border-radius:8px;color:var(--text-muted);font-size:12px}
.pmo-b .pill{display:inline-block;padding:1px 8px;border-radius:10px;font-size:11px;font-weight:600;color:#fff}
.pmo-b .pill.ok{background:var(--green-500)}.pmo-b .pill.warn{background:var(--orange-500)}.pmo-b .pill.bad{background:var(--red-500)}.pmo-b .pill.gray{background:var(--gray-500)}
/* Attention: filas jerárquicas */
.pmo-b .rows{display:flex;flex-direction:column;gap:8px}
.pmo-b .row{border:1px solid var(--border-color);border-radius:10px;padding:10px 12px;cursor:pointer;background:var(--card-bg)}
.pmo-b .row:hover{background:var(--subtle-fg,var(--gray-50))}
.pmo-b .row-head{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:6px}
.pmo-b .pname{font-weight:700;font-size:14px}
.pmo-b .cust{color:var(--text-muted);font-size:12px}
.pmo-b .chips{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:6px}
.pmo-b .chip{font-size:11px;color:var(--text-muted);background:var(--subtle-fg,var(--gray-100));border-radius:8px;padding:2px 8px}
.pmo-b .chip b{color:var(--text-color)}
.pmo-b .chip.bad b{color:var(--red-600)}
.pmo-b .reason{font-size:12px;color:var(--text-muted);line-height:1.35}
/* tablas (delayed / customers) */
.pmo-b .wrap{overflow-x:auto;border:1px solid var(--border-color);border-radius:8px}
.pmo-b table{width:100%;border-collapse:collapse;min-width:520px}
.pmo-b th,.pmo-b td{padding:7px 9px;border-bottom:1px solid var(--border-color);text-align:left;font-size:12px;vertical-align:top}
.pmo-b thead th{background:var(--subtle-fg,var(--gray-100));color:var(--text-muted);font-weight:600;text-transform:uppercase;font-size:10px;letter-spacing:.02em;white-space:nowrap}
.pmo-b tbody tr{cursor:pointer}.pmo-b tbody tr:hover{background:var(--subtle-fg,var(--gray-50))}
.pmo-b td.num{text-align:right;white-space:nowrap}.pmo-b td.bad{color:var(--red-600);font-weight:600}
.pmo-b .reasonc{color:var(--text-muted);font-size:11px}
.pmo-b .sec2{margin-top:16px}

script:
const root=root_element;const el=root.querySelector(".pmo-b");
const T=(typeof __==="function")?__:(s)=>s;
const esc=(s)=>s==null?"":String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const nz=(v)=>(v===null||v===undefined||v==="")?"–":v;
const hpill={on_track:"ok",at_risk:"warn",deviated:"bad"};
function fail(){el.innerHTML=`<div class="empty">${esc(T("Could not load this PMO panel."))}</div>`;}

function attention(rows){
  if(!rows||!rows.length) return `<div class="empty">${esc(T("No projects require attention right now."))}</div>`;
  let h=`<div class="rows">`;
  for(const r of rows){
    h+=`<div class="row" data-project="${esc(r.project)}">
      <div class="row-head"><span class="pname">${esc(r.project_name||r.project)}</span>
        <span class="pill ${hpill[r.health_key]||'gray'}">${esc(r.health)}</span>
        ${r.customer?`<span class="cust">${esc(r.customer)}</span>`:""}</div>
      <div class="chips">
        <span class="chip">${esc(T("Forecast end"))}: <b>${nz(r.forecast_end)}</b></span>
        <span class="chip">${esc(T("Slip vs BL"))}: <b>${nz(r.slip_baseline)}</b></span>
        <span class="chip ${(r.slip_committed>0)?'bad':''}">${esc(T("Slip vs commit"))}: <b>${nz(r.slip_committed)}</b></span>
        <span class="chip ${(r.overdue>0)?'bad':''}">${esc(T("Overdue"))}: <b>${nz(r.overdue)}</b></span>
        <span class="chip">${esc(T("Planned/Actual (h)"))}: <b>${nz(r.planned_hours)} / ${nz(r.actual_hours)}</b></span>
      </div>
      <div class="reason">${esc(r.reason)}</div></div>`;
  }
  return h+`</div>`;
}
function delayed(rows){
  if(!rows||!rows.length) return `<div class="empty">${esc(T("No delayed tasks among your projects."))}</div>`;
  let h=`<div class="wrap"><table><thead><tr>
    <th>${esc(T("Task"))}</th><th>${esc(T("Project"))}</th><th>${esc(T("Expected end"))}</th>
    <th class="hide-sm">${esc(T("Committed"))}</th><th class="num">${esc(T("Delay (d)"))}</th><th>${esc(T("Status"))}</th>
  </tr></thead><tbody>`;
  for(const r of rows){
    h+=`<tr data-task="${esc(r.task)}"><td><b>${esc(r.subject||r.task)}</b>${r.assignee?`<div class="reasonc">${esc(r.assignee)}</div>`:""}</td>
      <td>${esc(r.project)}</td><td>${nz(r.exp_end_date)}</td><td class="hide-sm">${nz(r.pmo_deadline)}</td>
      <td class="num bad">${nz(r.delay_days)}</td><td>${esc(r.status)}</td></tr>`;
  }
  return h+`</tbody></table></div>`;
}
el.addEventListener("click",(e)=>{
  const pr=e.target.closest("[data-project]"); if(pr){frappe.set_route("pmo_project_control",pr.getAttribute("data-project"));return;}
  const tk=e.target.closest("[data-task]"); if(tk){frappe.set_route("Form","Task",tk.getAttribute("data-task"));return;}
});
frappe.xcall("pmo.dashboard.attention_block").then((d)=>{
  el.innerHTML=`${attention(d.attention)}`+`<div class="sec2"><h3>${esc(T("Most overdue tasks"))}</h3>${delayed(d.delayed_tasks)}</div>`;
}).catch((e)=>{fail();console.error("PMO attention",e);});

const root=root_element;const el=root.querySelector(".pmo-gov");
const T=(typeof __==="function")?__:(s)=>s;
const esc=(s)=>s==null?"":String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
// Paleta e iconos POR ETAPA — presentación pura (estilo por clave de control; NO reglas de lifecycle).
const SVG={
  acta:'<path d="M3 1.5A.5.5 0 0 1 3.5 1H9l4 4v9a.5.5 0 0 1-.5.5h-9A.5.5 0 0 1 3 14z" fill="none" stroke="currentColor" stroke-width="1.2"/><path d="M9 1.5V5h3.5" fill="none" stroke="currentColor" stroke-width="1.2"/>',
  baseline:'<path d="M2.5 14V8.5M6.5 14V3.5M10.5 14V10M14.5 14V6" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>',
  risk:'<path d="M8 1.6 3 3.5v3.9c0 3 2.2 5.3 5 6.4 2.8-1.1 5-3.4 5-6.4V3.5z" fill="none" stroke="currentColor" stroke-width="1.2"/><path d="M8 5.5v3.2M8 10.4v.1" stroke="currentColor" stroke-width="1.3" stroke-linecap="round"/>',
  change:'<path d="M3.5 5.5h8l-2.2-2.2M12.5 10.5h-8l2.2 2.2" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round"/>',
  closure:'<path d="M4 14.5V2M4 2.5h7.2l-1.4 2.3L11.2 7H4" fill="none" stroke="currentColor" stroke-width="1.25" stroke-linecap="round" stroke-linejoin="round"/>',
  review:'<path d="M8 1.9l1.75 3.8 4.15.5-3.05 2.85.8 4.15L8 11.85 4.35 13.2l.8-4.15L2.1 6.2l4.15-.5z" fill="currentColor"/>'
};
const PAL={acta:"#2f6fed",baseline:"#6a2be0",risk:"#e8590c",change:"#0f766e",closure:"#c31336",review:"#6d28d9"};
const rgba=(hex,a)=>{const n=parseInt(hex.slice(1),16);return `rgba(${(n>>16)&255},${(n>>8)&255},${n&255},${a})`;};
const ki={
  pmo:'<circle cx="5.5" cy="6" r="2.2" fill="currentColor"/><circle cx="11" cy="6.6" r="1.9" fill="currentColor"/><path d="M1.5 13.5c0-2.4 1.9-3.8 4-3.8s4 1.4 4 3.8" fill="none" stroke="currentColor" stroke-width="1.3"/><path d="M10.2 9.9c1.9.1 3.3 1.5 3.3 3.6" fill="none" stroke="currentColor" stroke-width="1.3"/>',
  pm:'<circle cx="8" cy="5" r="2.6" fill="currentColor"/><path d="M2.8 14c0-2.9 2.3-4.6 5.2-4.6S13.2 11.1 13.2 14" fill="none" stroke="currentColor" stroke-width="1.4"/>',
  ex:'<circle cx="8" cy="8" r="6" fill="none" stroke="currentColor" stroke-width="1.4"/><path d="M3.9 3.9l8.2 8.2" stroke="currentColor" stroke-width="1.4"/>'
};
const svg=(inner)=>`<svg viewBox="0 0 16 16" xmlns="http://www.w3.org/2000/svg">${inner}</svg>`;
function fail(e){el.innerHTML=`<div class="empty">${esc(T("Could not load this PMO panel."))}</div>`;if(e)console.error("PMO governance",e);}
function go(r){
  if(r.route){frappe.set_route(r.route,r.target_name);}
  else if(r.target_name){frappe.set_route("Form",r.target_doctype,r.target_name);}
  else if(r.target_doctype){frappe.new_doc(r.target_doctype,{project:r.project});}
}
function stageCard(s){
  const col=PAL[s.control]||"var(--text-muted)";
  return `<div class="stage" style="background:${rgba((PAL[s.control]||"#888888"),0.06)};border-color:${rgba((PAL[s.control]||"#888888"),0.25)}">`
    +`<div class="sh"><span class="si" style="background:${rgba((PAL[s.control]||"#888888"),0.14)};color:${col}">${svg(SVG[s.control]||"")}</span>`
    +`<span class="sn">${esc(s._n)}. ${esc(s.control_label)}</span></div>`
    +`<div class="sd">${esc(s.description)}</div>`
    +`<div class="st"><span class="mk ok">✓</span><b>${esc(s.completo)}</b> ${esc(T("Complete"))}</div>`
    +`<div class="st"><span class="mk pend">!</span><b>${esc(s.pendiente)}</b> ${esc(T("Pending"))}</div>`
    +`</div>`;
}
function kpi(v,l,sub,cls,icon){
  const col=cls==="pmo"?"var(--red-600,#c0392b)":cls==="pm"?"var(--orange-600,#e8951b)":"var(--blue-600,#1579d0)";
  const tint=cls==="pmo"?rgba("#e03636",0.10):cls==="pm"?rgba("#e8951b",0.12):rgba("#2490ef",0.10);
  return `<div class="kpi" style="background:${tint};border-color:${rgba((cls==="pmo"?"#e03636":cls==="pm"?"#e8951b":"#2490ef"),0.25)}">`
    +`<span class="ki" style="color:${col}">${svg(icon)}</span>`
    +`<div><div style="display:flex;align-items:baseline;gap:8px"><span class="v">${esc(v??0)}</span>`
    +`<span class="kt" style="color:${col}">${esc(l)}</span></div><div class="ks">${esc(sub)}</div></div></div>`;
}
function age(r){
  if(r.age_days!=null) return `<span class="age">${r.age_days} d</span>`;
  if(r.since_date) return `<span class="age">${esc(r.since_date)}</span>`;
  return `<span class="muted">—</span>`;
}
function chip(control,label){const c=PAL[control]||"#888";return `<span class="chip" style="background:${rgba(c,0.12)};color:${c}">${esc(label)}</span>`;}
function respBadge(o){const c=o==="PMO"?"pmo":"pm";return `<span class="badge ${c}">${esc(o)}</span>`;}
function inbox(items){
  if(!items||!items.length) return `<div class="empty">${esc(T("No pending governance actions."))}</div>`;
  let h=`<table><thead><tr>`
    +`<th>${esc(T("Project"))}</th><th>${esc(T("Project Manager"))}</th><th>${esc(T("Control"))}</th>`
    +`<th>${esc(T("Situation"))}</th><th>${esc(T("Age / Date"))}</th><th>${esc(T("Owner"))}</th><th>${esc(T("Review"))}</th>`
    +`</tr></thead><tbody>`;
  for(const r of items){
    h+=`<tr>`
      +`<td><span class="pname" data-p="${esc(r.project)}">${esc(r.project_name||r.project)}</span></td>`
      +`<td>${r.project_manager?esc(r.project_manager):'<span class="muted">—</span>'}</td>`
      +`<td>${chip(r.control,r.control_label)}</td>`
      +`<td>${esc(r.situation)}${r.priority?(' <b>['+esc(T(r.priority))+']</b>'):''}</td>`
      +`<td>${age(r)}</td>`
      +`<td>${respBadge(r.action_owner)}</td>`
      +`<td><span class="rev" data-i="${esc(r._i)}">${esc(T("Review"))} ›</span></td>`
      +`</tr>`;
  }
  return h+`</tbody></table>`;
}
function excludedTable(rows){
  if(!rows||!rows.length) return `<div class="empty">${esc(T("No projects excluded from governance."))}</div>`;
  let h=`<table><thead><tr>`
    +`<th>${esc(T("Project"))}</th><th>${esc(T("Project Manager"))}</th><th>${esc(T("Exclusion reason"))}</th>`
    +`<th>${esc(T("Authorized by"))}</th><th>${esc(T("Date"))}</th>`
    +`</tr></thead><tbody>`;
  for(const r of rows){
    h+=`<tr>`
      +`<td><span class="pname" data-p="${esc(r.project)}">${esc(r.project_name||r.project)}</span></td>`
      +`<td>${r.project_manager?esc(r.project_manager):'<span class="muted">—</span>'}</td>`
      +`<td>${esc(r.reason||"—")}</td>`
      +`<td>${r.exempt_by?esc(r.exempt_by):'<span class="muted">—</span>'}</td>`
      +`<td>${r.exempt_on?esc((frappe.datetime&&frappe.datetime.str_to_user)?frappe.datetime.str_to_user(r.exempt_on):String(r.exempt_on).slice(0,10)):'<span class="muted">—</span>'}</td>`
      +`</tr>`;
  }
  return h+`</tbody></table>`;
}
frappe.xcall("pmo.governance_inbox.governance_board").then((d)=>{
  const k=d.kpis||{};const items=(d.items||[]).map((r,i)=>({...r,_i:i}));
  const stages=(d.stages||[]).map((s,i)=>({...s,_n:i+1}));const excluded=d.excluded||[];
  el.innerHTML=
    `<div class="desc">${esc(T("Supervision of the project governance cycle compliance: what is missing, why, and who must act."))}</div>`
    +`<h3 class="cyc">${esc(T("Governance cycle of the project"))}</h3>`
    +`<div class="cycle">`+stages.map(stageCard).join('<span class="arrow">›</span>')+`</div>`
    +`<div class="kpis">`
      +kpi(k.pmo_actions,T("Requires PMO action"),T("Items requiring PMO review or decision."),"pmo",ki.pmo)
      +kpi(k.pm_actions,T("Requires PM action"),T("Items requiring the Project Manager's attention."),"pm",ki.pm)
      +kpi(k.exempt_active,T("Active projects excluded"),T("Projects not subject to governance."),"ex",ki.ex)
    +`</div>`
    +`<h3>${esc(T("Require attention"))} (${items.length})</h3>`
    +`<div class="sub">${esc(T("Projects with pending or in-review governance items."))}</div>`
    +inbox(items)
    +`<h3>${esc(T("Projects not subject to governance"))} (${excluded.length})</h3>`
    +`<div class="sub">${esc(T("Active projects formally excluded from PMO governance."))}</div>`
    +excludedTable(excluded);
  el.querySelectorAll(".pname").forEach(n=>n.addEventListener("click",()=>frappe.set_route("Form","Project",n.getAttribute("data-p"))));
  el.querySelectorAll(".rev[data-i]").forEach(n=>n.addEventListener("click",()=>go(items[+n.getAttribute("data-i")])));
}).catch(fail);
